int add_route_to_fib6(struct fib6_node *root, struct rt6_info *rt, struct nl_info *info) {
    int ret;

    if (!root || !rt || !info) {
        return -EINVAL;
    }

    if ((info->nlflags & RTM_F_CREATE) == 0) {
        return -EINVAL;
    }

    ret = fib6_add_1(root, rt, info);
    if (ret < 0) {
        return ret;
    }

    if (rt->rt6i_src) {
        struct fib6_node *subtree = create_subtree_node();
        if (!subtree) {
            return -ENOMEM;
        }

        ret = add_source_route(subtree, rt);
        if (ret < 0) {
            free_subtree_node(subtree);
            return ret;
        }

        rt->rt6i_refcnt++;
    }

    return 0;
}
